ee:message.ee:set-payload:
%dw 2.0
output application/xml
---
"soap:Envelope" @("xmlns:soap":"http://www.w3.org/2003/05/soap-envelope","xmlns:mdm":"http://www.etb.com.co/Gateway/MDM_Data_Services"): {
    "soap:Header": null,
    "soap:Body": {
        "mdm:Set_Customer_Contact": {
            "mdm:WSRequestHeader": {
                "mdm:system": {
                    "mdm:name": vars.headers.name default "Salesforce",
                    "mdm:correlationId": vars.headers."x-correlation-id" default correlationId,
                    "mdm:processingServer": "MDM"
                }
            },
            "mdm:WSRequestBody": {
                "mdm:Id_Cliente": payload.IntegrationIdCuenta,
                "mdm:Tipo_Documento_Contacto": payload.TipoDocumento,
                "mdm:Numero_Documento_Contacto": payload.NumeroDocumento,
                "mdm:Nombre_Contacto": trim(trim(payload.Nombres  default "") ++ " " ++ trim(trim(payload.PrimerApellido default "") ++ " " ++ trim(payload.SegundoApellido default ""))),
                "mdm:Telefono_Contacto": payload.Telefono,
                "mdm:Movil_Contacto": payload.Celular,
                "mdm:Email_Contacto": payload.Correo,
                "mdm:set_type": "I",
                "mdm:Nombre_Individual": payload.Nombres,
                "mdm:Primer_Apellido": payload.PrimerApellido,
                "mdm:Segundo_Apellido": payload.SegundoApellido,
                "mdm:Usuario_Modificador": "ETB",
                "mdm:ATDP": {
                    "mdm:HABEAS_DATA": if(payload.HabeasData == "AUTORIZA") "True" else if(payload.HabeasData == "REVOCATORIA") "False" else if(payload.HabeasData == "SUPRIMIR") "True" else null,
                    "mdm:FECHA": now()
                }
            }
        }
    }
}
